from typing import List

def parse_music(music_string: str) -> List[int]:
    def map_note_to_beats(note: str) -> int:
        if note == 'o':
            return 4
        elif note == 'o|':
            return 2
        elif note == '.|':
            return 1
        else:
            raise ValueError("Invalid musical note format")

    def validate_input_string(music_string: str) -> bool:
        notes = music_string.split()
        for note in notes:
            if note not in ['o', 'o|', '.|']:
                return False
            if note == 'o' and len(notes) > 1:
                return False
        return True

    if not validate_input_string(music_string):
        raise ValueError("Input string is not correctly formatted according to the legend")

    notes = music_string.split()
    beats = [map_note_to_beats(note) for note in notes]

    return beats
